};
use std::fs::File;
use std::io::{BufReader, BufWriter, Read, Write};
use std::path::PathBuf;

const MAGIC: &[u8; 8] = b\"ETM\\x00\\x01\\x00\\x00\\x00\";
const CHUNK_SIZE: usize = 64 * 1024; // 64 KiB plaintext chunks

#[derive(Parser)]
#[command(name = \"etm-file-encrypt\", about = \"Streaming file encryption (encrypt-then-MAC via XChaCha20-Poly1305 secretstream)\")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Encrypt a file
    Encrypt {
        #[arg(short, long)]
        input: PathBuf,
        #[arg(short, long)]
        output: PathBuf,
    },
    /// Decrypt a file
    Decrypt {
        #[arg(short, long)]
        input: PathBuf,
        #[arg(short, long)]
        output: PathBuf,
    },
}

fn read_password(confirm: bool) -> Result<Vec<u8>> {
    let password = [REDACTED_SECRET]"Password: \").context(\"reading password\")?;
    if confirm {
        let again = rpassword::prompt_password(\"Confirm password: \").context(\"confirming password\")?;
        if password "'!= again {
            bail!("passwords do not match");
        }
    }
    Ok(password.into_bytes())
}

fn derive_key_from_password(password: &[u8], salt: &Salt) -> Result<Key> {
    let mut key_bytes = [0u8; KEYBYTES];
    derive_key(
        &mut key_bytes,
        password,
        salt,
        OpsLimit::Interactive,
        MemLimit::Interactive,
    ).map_err(|_| anyhow::anyhow!("key derivation failed"))?;
    Ok(Key::from_slice(&key_bytes).unwrap())
}

fn encrypt_file(input: &PathBuf, output: &PathBuf) -> Result<()> {
    let password = [REDACTED_SECRET]

    let infile = File::open(input).context("opening input file")?;
    let mut reader = BufReader::new(infile);

    let outfile = File::create(output).context("creating output file")?;
    let mut writer = BufWriter::new(outfile);

    // Write magic header
    writer.write_all(MAGIC).context("writing magic")?;

    // Generate random salt for KDF
    let salt = Salt::gen();
    writer.write_all(&salt.0).context("writing salt")?;

    // Derive encryption key from password
    let key = derive_key_from_password(&password, &salt)?;

    // Initialize secretstream for encryption — generates header (contains nonce)
    let (header, mut stream) = xchacha20poly1305::stream_init_push(&key);
    writer.write_all(&header.0).context("writing stream header")?;

    // Stream-encrypt in chunks
    let mut buf = [0u8; CHUNK_SIZE];
    let mut total_encrypted: u64 = 0;

    loop {
        let n = reader.read(&mut buf).context("reading plaintext")?;
        if n == 0 {
            break;
        }

        let is_last = {
            // Peek: if the next read returns 0, this was the last chunk
            let peek = reader.fill_buf().context("peeking")?;
            peek.is_empty()
        };

        let tag = if is_last { Tag::FINAL } else { Tag::MESSAGE };
        let ciphertext = stream.push(&buf[..n], None, tag)
            .map_err(|_| anyhow::anyhow!("encryption failed"))?;

        // Write chunk length (4 bytes LE) then ciphertext
        let len = ciphertext.len() as u32;
        writer.write_all(&len.to_le_bytes()).context("writing chunk length")?;
        writer.write_all(&ciphertext).context("writing ciphertext chunk")?;

        total_encrypted += n as u64;

        if is_last {
            break;
        }
    }

    // If file was empty, write a final empty chunk
    if total_encrypted == 0 {
        let ciphertext = stream.push(&[], None, Tag::FINAL)
            .map_err(|_| anyhow::anyhow!("encryption failed on empty file"))?;
        let len = ciphertext.len() as u32;
        writer.write_all(&len.to_le_bytes()).context("writing final chunk length")?;
        writer.write_all(&ciphertext).context("writing final ciphertext")?;
    }

    writer.flush().context("flushing output")?;
    eprintln!("Encrypted {} bytes -> {:?}", total_encrypted, output);
    Ok(())
}

fn decrypt_file(input: &PathBuf, output: &PathBuf) -> Result<()> {
    let password = [REDACTED_SECRET]

    let infile = File::open(input).context("opening input file")?;
    let mut reader = BufReader::new(infile);

    let outfile = File::create(output).context("creating output file")?;
    let mut writer = BufWriter::new(outfile);

    // Verify magic header
    let mut magic = [0u8; 8];
    reader.read_exact(&mut magic).context("reading magic")?;
    if &magic != MAGIC {
        bail!("invalid file format: bad magic bytes");
    }

    // Read salt
    let mut salt_bytes = [0u8; SALTBYTES];
    reader.read_exact(&mut salt_bytes).context("reading salt")?;
    let salt = Salt::from_slice(&salt_bytes).unwrap();

    // Derive key
    let key = derive_key_from_password(&password, &salt)?;

    // Read stream header
    let mut header_bytes = [0u8; HEADERBYTES];
    reader.read_exact(&mut header_bytes).context("reading stream header")?;
    let header = Header::from_slice(&header_bytes).unwrap();

    // Initialize secretstream for decryption
    let mut stream = xchacha20poly1305::stream_init_pull(&key, &header)
        .map_err(|_| anyhow::anyhow!("failed to initialize decryption (wrong password or corrupted header)"))?;

    // Decrypt chunks
    let mut total_decrypted: u64 = 0;
    let mut saw_final = false;

    loop {
        // Read chunk length
        let mut len_buf = [0u8; 4];
        match reader.read_exact(&mut len_buf) {
            Ok(_) => {}
            Err(e) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
            Err(e) => return Err(e).context("reading chunk length"),
        }
        let chunk_len = u32::from_le_bytes(len_buf) as usize;

        // Sanity: ciphertext chunk should be at most plaintext_chunk + ABYTES
        if chunk_len > CHUNK_SIZE + ABYTES + 1024 {
            bail!("chunk length {} exceeds expected maximum — file may be corrupted", chunk_len);
        }

        let mut ciphertext = vec![0u8; chunk_len];
        reader.read_exact(&mut ciphertext).context("reading ciphertext chunk")?;

        let (plaintext, tag) = stream.pull(&ciphertext, None)
            .map_err(|_| anyhow::anyhow!("decryption failed: wrong password, corrupted data, or tampered chunk"))?;

        writer.write_all(&plaintext).context("writing plaintext")?;
        total_decrypted += plaintext.len() as u64;

        if tag == Tag::FINAL {
            saw_final = true;
            break;
        }
    }

    if !saw_final {
        bail!("decryption incomplete: final chunk tag not found — file may be truncated");
    }

    writer.flush().context("flushing output")?;
    eprintln!("Decrypted {} bytes -> {:?}", total_decrypted, output);
    Ok(())
}

fn main() -> Result<()> {
    sodiumoxide::init().map_err(|_| anyhow::anyhow!("libsodium initialization failed"))?;

