        let (d1, t1) = pull_stream.pull(&c1, None).unwrap();
        let (d2, t2) = pull_stream.pull(&c2, None).unwrap();
        let (d3, t3) = pull_stream.pull(&c3, None).unwrap();

        assert_eq!(t1, Tag::Message);
        assert_eq!(t2, Tag::Message);
        assert_eq!(t3, Tag::Final);
        assert_eq!(d1, chunk1);
        assert_eq!(d2, chunk2);
        assert_eq!(d3, chunk3);
    }

